use serde::{Deserialize, Serialize};
use std::collections::HashMap;

fn generate_analysis_report (extraction : & MoldExtraction , input_file : & str) -> Result < () > { let report_file = format ! ("{}_mold_report.rs" , input_file . trim_end_matches (".rs")) ; let analysis = & extraction . static_analysis ; let report_code = quote ! { pub mod mold_analysis_report { use super ::*; pub const TOTAL_COMPLEXITY : f64 = # (analysis . complexity_metrics . total_complexity) ; pub const PARSE_OPERATIONS : u32 = # (analysis . complexity_metrics . parse_operations) ; pub const VISIT_OPERATIONS : u32 = # (analysis . complexity_metrics . visit_operations) ; pub const TRANSFORM_OPERATIONS : u32 = # (analysis . complexity_metrics . transform_operations) ; pub const GENERATION_OPERATIONS : u32 = # (analysis . complexity_metrics . generation_operations) ; pub trait CompileTimeValidation { const IS_VALID : bool ; const COMPLEXITY_THRESHOLD : f64 = 10.0 ; fn validate () -> bool { Self :: IS_VALID && TOTAL_COMPLEXITY < Self :: COMPLEXITY_THRESHOLD } } pub struct AnalyzedCode ; impl CompileTimeValidation for AnalyzedCode { const IS_VALID : bool = true ; } const _ : () = { assert ! (AnalyzedCode :: validate () , "Code complexity exceeds threshold") ; } ; pub mod patterns { pub const PATTERN_COUNT : usize = # (analysis . usage_patterns . len ()) ; } } } ; fs :: write (& report_file , report_code . to_string ()) ? ; println ! ("📋 Analysis report written to {}" , report_file) ; Ok (()) }